"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week", "month": "month", "months": "month"}
POSITIVE_INTEGER = re.compile(r"[1-9][0-9]*")
DURATION = re.compile(r"(?:([1-9][0-9]*)d)?(?:([1-9][0-9]*)h)?(?:([1-9][0-9]*)m)?")


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    until: dt.date = None
    times: int = None


def parse_duration(word):
    """'1h30m' -> 90. Returns None when the word is not a duration."""
    if not isinstance(word, str) or not word:
        return None
    match = DURATION.fullmatch(word.lower())
    if match is None:
        return None
    days, hours, minutes = (int(Decimal(part)) for part in match.groups(default="0"))
    return days * 1440 + hours * 60 + minutes


def format_duration(minutes):
    days, minutes = divmod(minutes, 1440)
    hours, mins = divmod(minutes, 60)
    parts = ((days, "d"), (hours, "h"), (mins, "m"))
    return "".join(f"{Decimal(amount)}{unit}" for amount, unit in parts if amount)


def _count(word):
    if POSITIVE_INTEGER.fullmatch(word):
        return int(Decimal(word))


def _date(word):
    if re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", word):
        return dt.date.fromisoformat(word)


def _time(word):
    if re.fullmatch(r"[0-9]{2}:[0-9]{2}", word):
        return dt.time.fromisoformat(word)


def _month_day(word):
    if word == "last":
        return word
    if re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        return int(word)


def _list(word, convert):
    items = [convert(item) for item in word.split(",")]
    if None not in items and len(set(items)) == len(items):
        return items


class _Words:
    def __init__(self, text):
        self.text = text
        self.words = list(re.finditer(r"[^ \t]+", text))
        self.index = 0

    @property
    def position(self):
        if self.index < len(self.words):
            return self.words[self.index].start()
        return len(self.text)

    def peek(self):
        if self.index < len(self.words):
            return self.words[self.index].group().lower()

    def fail(self, message):
        raise RuleSyntaxError(message, self.position, self.text)

    def take(self, what):
        word = self.peek()
        if word is None:
            self.fail(f"expected {what}, found end of rule")
        self.index += 1
        return word

    def expect(self, keyword):
        if self.peek() != keyword:
            self.fail(f"expected '{keyword}'")
        self.index += 1

    def convert(self, what, fn):
        at = self.position
        word = self.take(what)
        try:
            value = fn(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            raise RuleSyntaxError(f"expected {what}, found {word!r}", at, self.text)
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise PlanError("rule text must be a string")
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    if w.peek() is not None and w.peek().isdigit():
        rule.every = w.convert("a positive integer", _count)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    if w.peek() == "on":
        if rule.unit == "day":
            w.fail("'on' is not allowed with days")
        w.take("on")
        if rule.unit == "month":
            rule.on = w.convert("month days", lambda s: _list(s, _month_day))
            rule.on.sort(key=lambda day: 32 if day == "last" else day)
        else:
            rule.on = w.convert("weekdays", lambda s: _list(s, WEEKDAYS.index))
            rule.on.sort()
    w.expect("at")
    rule.at = w.convert("times", lambda s: _list(s, _time))
    rule.at.sort()
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    rule.start = w.convert("a date", _date)
    if w.peek() == "until":
        w.take("until")
        position = w.position
        rule.until = w.convert("a date", _date)
        if rule.until < rule.start:
            raise RuleSyntaxError("'until' precedes 'from'", position, text)
    elif w.peek() == "times":
        w.take("times")
        rule.times = w.convert("a positive integer", _count)
    if w.peek() is not None:
        w.fail(f"unexpected token {w.peek()!r}")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    out = ["every", str(Decimal(rule.every))]
    out.append(rule.unit if rule.every == 1 else rule.unit + "s")
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    out += ["at", ",".join(t.strftime("%H:%M") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    out += ["from", rule.start.isoformat()]
    if rule.until:
        out += ["until", rule.until.isoformat()]
    if rule.times:
        out += ["times", str(Decimal(rule.times))]
    return " ".join(out)
"""Convert between wall times and elapsed seconds on the UTC timeline."""

import datetime as dt
import re

from .errors import PlanError, describe_value

SECONDS_PER_DAY = 86400
LAST_SECOND = dt.date.max.toordinal() * SECONDS_PER_DAY - 1
LOCAL_MINUTE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}"
BOUND = re.compile(LOCAL_MINUTE + r"(?::[0-9]{2})?(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])")


def parse_local(text):
    if isinstance(text, str) and re.fullmatch(LOCAL_MINUTE, text):
        return dt.datetime.fromisoformat(text)
    raise ValueError("expected a local date-time")


def _instant(aware):
    days = aware.toordinal() - 1
    seconds = aware.hour * 3600 + aware.minute * 60 + aware.second
    return days * SECONDS_PER_DAY + seconds - int(aware.utcoffset().total_seconds())


def local_instant(local, zone):
    # fold=0 uses the pre-transition offset, which also shifts gap times forward.
    return _instant(local.replace(tzinfo=zone, fold=0))


def parse_bound(text):
    if isinstance(text, str) and BOUND.fullmatch(text):
        try:
            return _instant(dt.datetime.fromisoformat(text.replace("Z", "+00:00")))
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {describe_value(text)}")


def candidate_date(seconds):
    ordinal = seconds // SECONDS_PER_DAY + 1
    return dt.date.fromordinal(max(1, min(ordinal, dt.date.max.toordinal())))


def format_instant(seconds, zone):
    # The UTC date can lie just outside the calendar even for a valid local date.
    if not -SECONDS_PER_DAY < seconds <= LAST_SECOND + SECONDS_PER_DAY:
        raise OverflowError("timestamp is outside the calendar")
    clamped = max(0, min(seconds, LAST_SECOND))
    utc = dt.datetime.min.replace(tzinfo=dt.timezone.utc) + dt.timedelta(seconds=clamped)
    local = utc.astimezone(zone)
    if seconds != clamped:
        local += dt.timedelta(seconds=seconds - clamped)
    # Some historical offsets include seconds. The output format has minute precision.
    return local.isoformat(timespec="seconds")[:25]
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import gcd

from .instants import local_instant


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: int            # UTC seconds
    end: int


def _dates(rule, first, last):
    first = max(rule.start, first)
    if rule.until is not None:
        last = min(rule.until, last)
    if first > last:
        return

    first_day, last_day = first.toordinal(), last.toordinal()
    if rule.unit == "day":
        first_active = first_day + (rule.start.toordinal() - first_day) % rule.every
        for ordinal in range(first_active, last_day + 1, rule.every):
            yield dt.date.fromordinal(ordinal)
    elif rule.unit == "week":
        anchor = rule.start.toordinal() - rule.start.weekday()
        first_week = (first_day - anchor) // 7
        last_week = (last_day - anchor) // 7
        for week in range(first_week + (-first_week % rule.every), last_week + 1, rule.every):
            for weekday in rule.on:
                ordinal = anchor + week * 7 + weekday
                if first_day <= ordinal <= last_day:
                    yield dt.date.fromordinal(ordinal)
    else:
        anchor = rule.start.year * 12 + rule.start.month - 1
        first_month = first.year * 12 + first.month - 1
        last_month = last.year * 12 + last.month - 1
        first_active = first_month + (anchor - first_month) % rule.every
        # Only a request for the 29th depends on leap years, which repeat every 400 years.
        calendar_months = 4800 if 29 in rule.on else 12
        cycle = calendar_months // gcd(calendar_months, rule.every)
        empty_months = 0
        for month_index in range(first_active, last_month + 1, rule.every):
            year, month_offset = divmod(month_index, 12)
            month = month_offset + 1
            month_length = calendar.monthrange(year, month)[1]
            days = {month_length if item == "last" else item
                    for item in rule.on if item == "last" or item <= month_length}
            if not days:
                empty_months += 1
                if empty_months == cycle:
                    return
                continue
            empty_months = 0
            for day in sorted(days):
                date = dt.date(year, month, day)
                if first <= date <= last:
                    yield date


def candidates(ruledef, first, last):
    """Yield surviving keys and UTC starts in an inclusive nominal date range."""
    rule = ruledef.rule
    remaining = rule.times
    first_date = rule.start if remaining is not None else first
    for day in _dates(rule, first_date, last):
        starts = set()
        for time in rule.at:
            local = dt.datetime.combine(day, time)
            start = local_instant(local, ruledef.tz)
            if start in starts:
                continue
            starts.add(start)
            if day >= first:
                yield local.isoformat(timespec="minutes"), start
            if remaining is not None:
                remaining -= 1
                if remaining == 0:
                    return
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
from dataclasses import dataclass
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from .errors import PlanError, RuleSyntaxError, describe_value
from .expand import candidates
from .instants import local_instant, parse_local
from .rules import Rule, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int


@dataclass
class Override:
    action: str
    to: int = None
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # rule id -> {key: Override}
    min_segment: int


def _zone(name, context):
    if (isinstance(name, str) and name not in ("localtime", "posixrules")
            and not name.startswith(("posix/", "right/"))):
        try:
            return ZoneInfo(name)
        except (ValueError, ZoneInfoNotFoundError, OSError):
            pass
    raise PlanError(f"{context}: unknown timezone {describe_value(name)}")


def _override_key(ruledef, key):
    if isinstance(key, str) and len(key) == 10 and len(ruledef.rule.at) == 1:
        key += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
    try:
        parse_local(key)
    except ValueError as exc:
        raise PlanError(f"rule {ruledef.id}: invalid override key {describe_value(key)}") from exc
    return key


def _load_override(ruledef, item):
    action = item.get("action")
    if action == "cancel":
        return Override(action)
    if action != "move":
        raise PlanError(f"rule {ruledef.id}: unknown override action {describe_value(action)}")

    try:
        to = parse_local(item.get("to"))
    except ValueError as exc:
        raise PlanError(f"rule {ruledef.id}: move override needs a valid 'to'") from exc
    minutes = None
    if "for" in item:
        minutes = parse_duration(item["for"])
        if minutes is None:
            raise PlanError(f"rule {ruledef.id}: invalid move duration {describe_value(item['for'])}")
    return Override(action, local_instant(to, ruledef.tz), minutes)


def _missing_override_key(ruledef, overrides):
    if ruledef.rule.times is None:
        for key in overrides:
            day = dt.date.fromisoformat(key[:10])
            if not any(candidate == key for candidate, _ in candidates(ruledef, day, day)):
                return key
        return None

    missing = set(overrides)
    first = dt.date.fromisoformat(min(missing)[:10])
    last = dt.date.fromisoformat(max(missing)[:10])
    for key, _ in candidates(ruledef, first, last):
        missing.discard(key)
        if not missing:
            return None
    return min(missing)


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"], "plan")
    if not isinstance(raw.get("rules"), list):
        raise PlanError("plan rules must be a list")

    rules = {}
    for index, item in enumerate(raw["rules"]):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index} must be an object")
        rid = item.get("id")
        if not isinstance(rid, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
            raise PlanError(f"rule #{index} has invalid id {describe_value(rid)}")
        if rid in rules:
            raise PlanError(f"duplicate rule id {rid!r}")
        if not isinstance(item.get("rule"), str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        try:
            rule = parse_rule(item["rule"])
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, exc.text) from exc
        tz = _zone(item["timezone"], f"rule {rid}") if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError(f"rule {rid}: priority must be an integer")
        rules[rid] = RuleDef(index, rid, rule, tz, priority)

    raw_overrides = raw.get("overrides", [])
    if not isinstance(raw_overrides, list):
        raise PlanError("plan overrides must be a list")
    overrides = {}
    for item in raw_overrides:
        if not isinstance(item, dict):
            raise PlanError("override must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str) or rid not in rules:
            raise PlanError(f"override for unknown rule {describe_value(rid)}")
        ruledef = rules[rid]
        key = _override_key(ruledef, item.get("key"))
        rule_overrides = overrides.setdefault(rid, {})
        if key in rule_overrides:
            raise PlanError(f"rule {rid}: duplicate override for {key}")
        rule_overrides[key] = _load_override(ruledef, item)

    for rid, rule_overrides in overrides.items():
        missing = _missing_override_key(rules[rid], rule_overrides)
        if missing is not None:
            raise PlanError(f"rule {rid}: override key {missing} is not an occurrence")

    min_segment = 0
    if "min_segment" in raw:
        min_segment = parse_duration(raw["min_segment"])
        if min_segment is None:
            raise PlanError(f"invalid min_segment {describe_value(raw['min_segment'])}")
    return Plan(list(rules.values()), overrides, min_segment)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import heapq

from .errors import PlanError
from .expand import Occurrence, candidates
from .instants import SECONDS_PER_DAY, candidate_date, format_instant, parse_bound
from .plan import load_plan


def _collect(plan, lo, hi):
    found = []
    # A nominal local time is its UTC instant plus an offset of less than a day.
    last = candidate_date(hi + SECONDS_PER_DAY)
    for ruledef in plan.rules:
        duration = ruledef.rule.minutes * 60
        first = candidate_date(lo - duration - SECONDS_PER_DAY)
        overrides = plan.overrides.get(ruledef.id, {})
        for key, start in candidates(ruledef, first, last):
            end = start + duration
            if key not in overrides and start < hi and end > lo:
                found.append(Occurrence(ruledef, key, start, end))

        for key, override in overrides.items():
            if override.action == "move":
                start = override.to
                end = start + (duration if override.minutes is None else override.minutes * 60)
                if start < hi and end > lo:
                    found.append(Occurrence(ruledef, key, start, end))
    return found


def _as_dict(occ, start, end):
    try:
        return {
            "rule": occ.rule.id,
            "key": occ.key,
            "start": format_instant(start, occ.rule.tz),
            "end": format_instant(end, occ.rule.tz),
        }
    except OverflowError as exc:
        raise PlanError(f"rule {occ.rule.id}: timestamp is outside the supported calendar") from exc


def _query(raw, start, end):
    plan = load_plan(raw)
    lo, hi = parse_bound(start), parse_bound(end)
    if lo >= hi:
        raise PlanError("end must be after start")
    return plan, lo, hi, _collect(plan, lo, hi)


def occurrences(plan, start, end):
    _, _, _, found = _query(plan, start, end)
    found.sort(key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in found]


def _visible_segments(found):
    # Sweep the whole intervals. The heap contains ranks of started occurrences.
    found.sort(key=lambda occ: (-occ.rule.priority, occ.start, occ.rule.index, occ.key))
    starting = {}
    for rank, occ in enumerate(found):
        starting.setdefault(occ.start, []).append(rank)
    boundaries = sorted(starting.keys() | {occ.end for occ in found})
    active = []
    winner = None
    segment_start = None
    for point in boundaries:
        for rank in starting.get(point, ()):
            heapq.heappush(active, rank)
        while active and found[active[0]].end <= point:
            heapq.heappop(active)
        current = active[0] if active else None
        if current != winner:
            if winner is not None:
                yield found[winner], segment_start, point
            winner = current
            segment_start = point


def agenda(plan, start, end):
    plan_obj, lo, hi, found = _query(plan, start, end)
    minimum = plan_obj.min_segment * 60
    rows = []
    for occ, start, end in _visible_segments(found):
        lost_time = start != occ.start or end != occ.end
        if lost_time and end - start < minimum:
            continue
        start, end = max(start, lo), min(end, hi)
        if start < end:
            rows.append(_as_dict(occ, start, end))
    return rows

